void secp256r1_mult_iss(const uint32_t in[16], uint32_t out[16]) {
  // Comba product scanning; 96-bit accumulator r2:(r1:r0) held as r2 + 64-bit lo.
  uint64_t lo = 0;
  uint32_t r2 = 0;
  for (int k = 0; k < 15; ++k) {
    int i0 = k > 7 ? k - 7 : 0;
    int i1 = k < 7 ? k : 7;
    for (int i = i0; i <= i1; ++i) {
      uint64_t p = (uint64_t)in[i] * (uint64_t)in[8 + (k - i)];
      uint64_t s = lo + p;
      r2 += (s < lo) ? 1u : 0u;
      lo = s;
    }
    out[k] = (uint32_t)lo;
    lo = (lo >> 32) | ((uint64_t)r2 << 32);
    r2 = 0;
  }
  out[15] = (uint32_t)lo;
}

