  const uint32_t P[8] = {0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0u, 0u, 0u, 1u, 0xFFFFFFFFu};
  uint32_t D[8];
  uint32_t b = 0;
  for (int i = 0; i < 8; ++i) {
    uint64_t d = (uint64_t)in[i] - (uint64_t)in[8 + i] - (uint64_t)b;
    D[i] = (uint32_t)d;
    b = (uint32_t)(d >> 63);
  }
  uint32_t m = 0u - b;
  uint64_t carry = 0;
  for (int i = 0; i < 8; ++i) {
    uint64_t s = (uint64_t)D[i] + (uint64_t)(P[i] & m) + carry;
    out[i] = (uint32_t)s;
    carry = s >> 32;
  }
  for (int i = 8; i < 16; ++i) out[i] = 0;
}
